-- 0010: 상황 점수 2차 조정 — 카테고리(아우터/상의/하의/신발/가방)별로 데일리·출근·데이트 규칙을 따로 둠 (2026-10-02)
-- 0009 위에 그대로 덮어써도 되고, 0009 없이 단독 실행해도 같은 결과(상품 이름 기준으로 전부 다시 계산).
-- 되돌리려면 0008_catalog_seed.sql 의 situation 줄을 다시 실행.
update public.catalog_tags t set score = s.new_score from (select t2.id, case p.category when 'outer' then case t2.value when 'daily' then case when p.name ~ '시퀸|새틴|이브닝|진주단추|골드버튼' then -2 when p.name ~ '데님|셔츠 자켓|셔켓|가디건|나일론|점퍼|바시티|트러커|코듀로이|초어|워크웨어|유틸리티|야상|파카|아노락|트랙|집업|플리스|후드' then 3 when p.name ~ '트위드|볼레로|케이프|페플럼|퀼팅|패딩' then 1 else 2 end when 'work' then case when p.name ~ '볼레로|바이커|라이더|봄버|바시티|패딩|플리스|무스탕|셰르파|점퍼|후드|야상|파카|아노락|트랙|시퀸|새틴|퍼 자켓|케이프' then -2 when p.name ~ '트렌치|셔츠 자켓|셔켓|블레이저|테일러드|노카라|코트|오픈 가디건|포켓 롱|꽈배기|버튼 가디건|슬림 골지 가디건' then 3 when p.name ~ '트위드|가디건|자켓' then 2 else 1 end when 'date' then case when p.name ~ '후드|패딩|야상|바시티|플리스|아노락|점퍼|트랙|파카|워크웨어|초어|유틸리티|셰르파|무스탕' then -2 when p.name ~ '트위드|볼레로|케이프|진주단추|골드버튼|새틴|시퀸|페플럼|벨티드|골지 가디건|부클|판초|퍼 자켓|크롭 가디건' then 3 when p.name ~ '가디건|트렌치|자켓|코트' then 1 else 0 end end when 'top' then case t2.value when 'daily' then case when p.name ~ '새틴|이브닝|코르셋' then -1 when p.name ~ '티셔츠|맨투맨|후드|폴로|니트|스웨터|헨리넥|골지|플리스|저지' then 3 when p.name ~ '블라우스' then 1 else 2 end when 'work' then case when p.name ~ '나시|민소매|탱크|오프숄더|홀터|원숄더|코르셋|스위트하트|메쉬|후드|맨투맨|크로셰|탑$|벌룬|튜닉' then -2 when p.name ~ '티셔츠' then 1 when p.name ~ '프릴|러플|퍼프|레이스|플러터|리본|세일러|오간자|케이프소매' then 1 when p.name ~ '핀턱|오픈카라|타이넥|차이나카라|키홀|(^|[^티])셔츠|브이넥 랩|스퀘어넥 핀턱' then 3 when p.name ~ '블라우스|니트|가디건|폴로' then 2 else 0 end when 'date' then case when p.name ~ '후드|맨투맨|플리스|하프집업|저지 탑' then -3 when p.name ~ '프릴|러플|퍼프|레이스|플러터|리본|오간자|케이프소매|세일러|오프숄더|원숄더|홀터|랩|새틴|코르셋|스위트하트|벌룬|셔링|드레이프|페플럼' then 3 when p.name ~ '티셔츠' then 1 when p.name ~ '(^|[^티])셔츠' then 1 when p.name ~ '블라우스|골지|니트|가디건' then 2 else 0 end end when 'bottom' then case t2.value when 'daily' then case when p.name ~ '새틴|이브닝' then -1 when p.name ~ '데님|코튼|와이드|조거|카고|스웨트|트랙|쇼츠|린넨|캉캉|밴딩' then 3 when p.name ~ '스커트|슬랙스|팬츠' then 2 else 2 end when 'work' then case when p.name ~ '조거|트랙|스웨트|쇼츠|마이크로|미니|카고|나일론|버블|캉캉|새틴|레이스|비대칭' then -3 when p.name ~ '데님' then 0 when p.name ~ '슬랙스|테일러드|치노|펜슬|핀턱|A라인|스트레이트' then 3 when p.name ~ '미디|롱|맥시|스커트|팬츠' then 1 else 0 end when 'date' then case when p.name ~ '조거|트랙|스웨트|쇼츠|카고|나일론 팬츠' then -3 when p.name ~ '새틴|레이스|쉬폰|플리츠|랩|셔링|벌룬|캉캉|트위드|머메이드|비대칭|미디|맥시|미니 스커트' then 3 when p.name ~ '스커트' then 2 when p.name ~ '와이드 데님|슬랙스|팬츠' then 1 else 0 end end when 'shoes' then case t2.value when 'daily' then case when p.name ~ '이브닝|파티|펌프스' then -2 when p.name ~ '스니커즈|로퍼|플랫|캔버스|클로그|슬립온|메리제인|러닝|하이킹' then 3 when p.name ~ '샌들|뮬|슬리퍼|부츠|힐' then 1 else 1 end when 'work' then case when p.name ~ '이브닝|파티|슬리퍼|샌들|러닝|하이킹|스니커즈|컴뱃|윈터|레인|클로그|뮬' then -2 when p.name ~ '로퍼' then 3 when p.name ~ '플랫|발레리나|메리제인|슬링백' then 2 when p.name ~ '힐|펌프스' then 1 else 0 end when 'date' then case when p.name ~ '러닝|하이킹|스니커즈|컴뱃|윈터|레인|슬리퍼|클로그' then -2 when p.name ~ '힐|펌프스|슬링백|메리제인|발레리나|뮬|이브닝|파티|리본' then 3 when p.name ~ '로퍼|플랫|샌들' then 1 else 0 end end when 'bag' then case t2.value when 'daily' then case when p.name ~ '이브닝|클러치' then -2 when p.name ~ '크로스|호보|숄더|백팩|캔버스|쇼퍼|버킷|메신저|벨트백|새들' then 3 when p.name ~ '토트' then 2 else 1 end when 'work' then case when p.name ~ '이브닝|클러치|파우치|바스켓|비치|스트로|라탄|라피아|벨트백|메신저|네트' then -2 when p.name ~ '토트|구조적|박스|사첼|프레임' then 3 when p.name ~ '숄더|버킷|크로스|새들' then 2 when p.name ~ '백팩' then 1 else 0 end when 'date' then case when p.name ~ '백팩|벨트백|메신저|캔버스|쇼퍼|비치' then -2 when p.name ~ '클러치|이브닝|체인|미니|하프문|새들|바게트|리본|퀼팅|파우치|프레임' then 3 when p.name ~ '숄더|호보|토트|버킷|크로스' then 1 else 0 end end end as new_score from public.catalog_tags t2 join public.catalog_products p on p.id = t2.product_id where t2.dimension = 'situation') s where t.id = s.id and t.score is distinct from s.new_score;
